-- 584: Original BrillaPrep WASSCE Integrated Science sprint 3, part 1 of 8, practice questions (batch wassce-int-science-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_584_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_584_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_agric_b003_001', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following farming practices best conserves soil moisture during the dry season?', 'multiple_choice', NULL, '["A. Mulching the soil with plant residues","B. Burning the stubble after harvest","C. Ploughing the field along the slope","D. Removing all vegetation between crops"]', 'A', 'Mulching covers the soil with dry grass or crop residues, reducing direct evaporation and keeping the soil moist for longer. Burning stubble destroys organic matter and exposes the soil, ploughing along the slope encourages erosion, and removing vegetation leaves the soil bare to the sun. Therefore the correct answer is A: Mulching the soil with plant residues.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL),
('q_wisc_agric_b003_002', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which organism lives in the root nodules of legumes and improves soil fertility by fixing atmospheric nitrogen?', 'multiple_choice', NULL, '["A. Earthworm","B. Rhizobium bacterium","C. Mushroom fungus","D. Termite"]', 'B', 'Rhizobium bacteria live symbiotically in the root nodules of legumes such as cowpea and groundnut, converting atmospheric nitrogen into nitrates the plant can use. Earthworms only improve soil aeration and drainage, while mushrooms and termites are decomposers that do not fix nitrogen. Therefore the correct answer is B: Rhizobium bacterium.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL),
('q_wisc_agric_b003_003', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'In the food chain grass → grasshopper → lizard → hawk, the hawk is a', 'multiple_choice', NULL, '["A. producer","B. primary consumer","C. tertiary consumer","D. secondary consumer"]', 'C', 'Grass is the producer, the grasshopper that eats it is the primary consumer, the lizard that eats the grasshopper is the secondary consumer, and the hawk that eats the lizard is the tertiary consumer — the fourth trophic level. Therefore the correct answer is C: tertiary consumer.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL),
('q_wisc_agric_b003_004', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A maize farmer observes that the older leaves of his plants are turning yellow and growth is stunted. Which soil nutrient is most likely deficient?', 'multiple_choice', NULL, '["A. Phosphorus","B. Potassium","C. Calcium","D. Nitrogen"]', 'D', 'Nitrogen is needed for proteins and chlorophyll, and because it is mobile in the plant, deficiency shows first as yellowing (chlorosis) of the older leaves with stunted growth. Phosphorus deficiency gives poor root development and purplish leaves, while potassium deficiency scorches leaf edges. Therefore the correct answer is D: Nitrogen.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_agric_b003_005', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following is an important advantage of including a legume in a crop rotation programme?', 'multiple_choice', NULL, '["A. It restores nitrogen to the soil for the following crop","B. It removes all weeds from the field","C. It increases the salinity of the soil","D. It prevents all soil erosion"]', 'A', 'Legumes such as cowpea and groundnut host Rhizobium bacteria that fix atmospheric nitrogen into the soil, reducing the fertilizer needs of the next crop. Rotation cannot remove all weeds or prevent all erosion, and it does not increase soil salinity. Therefore the correct answer is A: It restores nitrogen to the soil for the following crop.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_agric_b003_006', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The process by which plants lose water vapour through their leaves to the atmosphere is called', 'multiple_choice', NULL, '["A. guttation","B. transpiration","C. photosynthesis","D. respiration"]', 'B', 'Transpiration is the loss of water vapour mainly through the stomata of leaves, and it drives the upward movement of water from the roots. Guttation is the loss of liquid water droplets at leaf edges, while photosynthesis makes food and respiration releases energy. Therefore the correct answer is B: transpiration.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
CREATE TABLE _migration_584_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_584_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_584_guard;
INSERT INTO _migration_584_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_584_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_584_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_584_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_584_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_584_guard;
INSERT INTO _migration_584_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_584_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_584_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_584_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_584_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
DROP TABLE _migration_584_guard;
DROP TABLE _migration_584_expected;
DROP TABLE _migration_584_expected_parts;
